1	/* ============================ Lái xe: chuyển động theo số liệu VF 3 ============================
2	   Mô hình "xe đạp" động học trên mặt bằng (spec §5.2): vị trí, hướng, tốc độ dọc có dấu, góc lái; không mô phỏng lốp, treo, trượt.
3	   - Tăng tốc: a = a0 không đổi tới 50 km/h (a0 = 50 km/h / t50, qua đúng mốc thứ nhất), sau đó a = a0 · v50 / v · (1 − u^k)
4	     với u = (v − v50) / (vMax − v50): giảm theo công suất không đổi và về 0 tại vMax. Số mũ k giải một lần (chia đôi) sao cho tới
5	     99 % vMax (27,5 m/s ≈ 100 km/h, vì đường cong chỉ tiệm cận vMax) đúng t100.
6	   - Lái: góc lái lớn nhất asin(wheelbase / turnRadius) (bán kính quay vòng tính ở tâm trục trước); tốc độ cao thì giới hạn thêm
7	     sao cho gia tốc ngang v² · tan(góc) / wheelbase ≤ latMax. Góc lái tiến về đích theo steerRate, tự trả về 0 theo steerReturn
8	     (cả hai là phần góc lái lớn nhất mỗi giây).
9	   - Phanh / lùi: phanh khi đang tiến; |v| < sim.revV mà giữ phanh, không ga thì lùi dần tới reverseMax; đang lùi mà đạp ga thì phanh
10	     về 0 rồi mới tiến. Nhả hết thì chậm dần theo coast, không tự lùi. Phanh tay hãm handBrake, không trượt. Dốc không đổi gia tốc.
11	   - drStep chia dt thành bước ≤ sim.dt (tối đa sim.steps bước, phần dư bỏ); mỗi bước dời thân xe bằng drMove (collide.ts);
12	     bị chặn thì v nhân phần quãng đã đi (đâm thẳng thì đứng hẳn, trượt dọc thì mất một phần).
13	   Không cấp phát mỗi khung (D-018). Không import three. */
14	import { CONFIG } from '../../config';
15	import { drGround, type DrNet } from './net';
16	import { drSpawnPose } from './roadData';
17	import { drMove, type DrPose, type DrBox } from './collide';
18	
19	export interface DrState extends DrPose { pitch: number; v: number; steer: number; wheel: number; braking: boolean; evac: number }   // v: m/s có dấu; steer: rad; wheel: góc quay bánh tích lũy (rad)
20	export interface DrInput { gas: number; brake: number; steer: number; hand: boolean }   // gas, brake: 0..1; steer: −1..1
21	
22	const CAR = CONFIG.drive.car, P = CONFIG.drive.perf, SIM = CONFIG.drive.sim;
23	const L = CAR.wheelbase;
24	const V50 = 50 / 3.6;                                                // m/s — mốc 0–50 km/h của t50
25	const STEER_GEOM = Math.asin(L / P.turnRadius);                     // rad — góc lái lớn nhất theo hình học
26	
27	/* ===== Đường cong tăng tốc ===== */
28	let A0 = NaN, KEXP = NaN;                                            // a0 (m/s²) và số mũ k, giải lười ở lần gọi đầu
29	function drAccelK(v: number, k: number): number {
30	  if (v <= V50) return A0;
31	  if (v >= P.vMax) return 0;
32	  const u = (v - V50) / (P.vMax - V50);
33	  return A0 * V50 / v * (1 - Math.pow(u, k));
34	}
35	/* Thời gian 0 → 0,99 vMax với số mũ k (tích phân dv / a, điểm giữa) */
36	function drT100(k: number): number {
37	  const vt = 0.99 * P.vMax, N = 2000, h = (vt - V50) / N;
38	  let t = V50 / A0;
39	  for (let i = 0; i < N; i++) t += h / drAccelK(V50 + (i + 0.5) * h, k);
40	  return t;
41	}
42	function drFitAccel(): void {
43	  A0 = V50 / P.t50;
44	  let lo = 0.2, hi = 50;                                             // k nhỏ ⇒ hãm sớm ⇒ chậm hơn: drT100 giảm theo k
45	  for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; if (drT100(m) > P.t100) lo = m; else hi = m; }
46	  KEXP = (lo + hi) / 2;
47	}
48	/* m/s² khi đạp hết ga ở tốc độ v ≥ 0 */
49	export function drAccel(v: number): number {
50	  if (Number.isNaN(KEXP)) drFitAccel();
51	  return drAccelK(v, KEXP);
52	}
53	
54	/* rad — góc lái lớn nhất ở tốc độ v (dấu bỏ qua) */
55	export function drSteerMax(v: number): number {
56	  const a = Math.abs(v);
57	  if (a < 1e-6) return STEER_GEOM;
58	  const lim = Math.atan(L * P.latMax / (a * a));
59	  return lim < STEER_GEOM ? lim : STEER_GEOM;
60	}
61	
62	const drToward0 = (v: number, d: number): number => v > 0 ? (v > d ? v - d : 0) : (v < -d ? v + d : 0);
63	
64	/* Dốc dọc từ cao độ mặt đường tại trục trước / sau; giữ giá trị cũ nếu một trục không có mặt đường cùng tầng */
65	function drPitch(s: DrState, net: DrNet): void {
66	  const fx = Math.cos(s.yaw) * L / 2, fz = -Math.sin(s.yaw) * L / 2;
67	  const yf = drGround(net, s.x + fx, s.z + fz, s.y), yr = drGround(net, s.x - fx, s.z - fz, s.y);
68	  if (!Number.isNaN(yf) && !Number.isNaN(yr)) s.pitch = Math.atan2(yf - yr, L);
69	}
70	
71	/* Xe mới ở chỗ xuất phát của slot, đứng yên trên mặt đường cao nhất tại đó (mặt cầu) */
72	export function drCreate(net: DrNet, slot: number): DrState {
73	  const sp = drSpawnPose(slot);
74	  let y = -Infinity;
75	  for (const p of net.pads) {
76	    if (sp.x < p.x0 || sp.x > p.x1 || sp.z < p.z0 || sp.z > p.z1) continue;
77	    if (p.gate !== undefined && net.closed.has(p.gate)) continue;
78	    y = Math.max(y, p.y(sp.x, sp.z));
79	  }
80	  const s: DrState = { x: sp.x, y: Number.isFinite(y) ? y : CONFIG.roadY, z: sp.z, yaw: sp.yaw, pitch: 0, v: 0, steer: 0, wheel: 0, braking: false, evac: 0 };
81	  drPitch(s, net);
82	  return s;
83	}
84	
85	const MOVED: DrPose = { x: 0, y: 0, z: 0, yaw: 0 };
86	
87	/* Một bước h ≤ sim.dt */
88	function drStep1(s: DrState, inp: DrInput, net: DrNet, boxes: DrBox[], nBoxes: number, h: number): void {
89	  const g = inp.gas > 0 ? (inp.gas < 1 ? inp.gas : 1) : 0, b = inp.brake > 0 ? (inp.brake < 1 ? inp.brake : 1) : 0;
90	  let v = s.v, braking = false;
91	  /* tốc độ */
92	  if (inp.hand) { v = drToward0(v, P.handBrake * h); braking = true; }
93	  else if (b > 0 && g === 0) {
94	    if (v >= SIM.revV) { v = Math.max(0, v - b * P.brake * h); braking = true; }                       // đang tiến: phanh
95	    else v = Math.max(-P.reverseMax, v - b * (v > 0 ? P.brake : drAccel(-v)) * h);                   // gần đứng / đang lùi: lùi dần
96	  } else if (g > 0 && b === 0) {
97	    if (v < 0) { v = Math.min(0, v + g * P.brake * h); braking = true; }                             // đang lùi: phanh về 0 rồi mới tiến
98	    else v = Math.min(P.vMax, v + g * drAccel(v) * h);
99	  } else if (g > 0 && b > 0) { v = drToward0(v, b * P.brake * h); braking = true; }
100	  else v = drToward0(v, P.coast * h);
101	  /* góc lái */
102	  const lim = drSteerMax(v), want = inp.steer > 1 ? 1 : inp.steer < -1 ? -1 : inp.steer;
103	  let st = s.steer;
104	  if (want === 0) st = drToward0(st, P.steerReturn * STEER_GEOM * h);
105	  else {
106	    const tgt = want * lim, back = Math.abs(tgt) < Math.abs(st) || tgt * st < 0;
107	    const d = (back ? Math.max(P.steerRate, P.steerReturn) : P.steerRate) * STEER_GEOM * h;
108	    st = st < tgt ? Math.min(tgt, st + d) : Math.max(tgt, st - d);
109	  }
110	  if (st > lim) st = lim; else if (st < -lim) st = -lim;
111	  /* dời thân xe */
112	  const dist = v * h, f = drMove(net, s, dist, dist * Math.tan(st) / L, boxes, nBoxes, MOVED);
113	  s.x = MOVED.x; s.y = MOVED.y; s.z = MOVED.z; s.yaw = MOVED.yaw;
114	  if (f < 1) v *= f;
115	  s.v = v; s.steer = st; s.braking = braking;
116	  s.wheel += dist * f / (CAR.wheelDia / 2);
117	  drPitch(s, net);
118	}
119	
120	/* Bước mô phỏng cho khung dài dt (s) */
121	export function drStep(s: DrState, inp: DrInput, net: DrNet, boxes: DrBox[], nBoxes: number, dt: number): void {
122	  let rem = dt;
123	  for (let k = 0; k < SIM.steps && rem > 1e-6; k++) {
124	    const h = rem < SIM.dt ? rem : SIM.dt;
