70	  const low: DrBox[] = [{ x: 30, y: -3, z: 20, yaw: 0, hl: 2, hw: 0.9 }];
71	  assert.equal(drMove(net, pose(15, 2.6, 20, 0), 30, 0, low, 1, out), 1);
72	});
