82	    assert.ok(Math.hypot(out.x - 30, out.z - 30) > 5.9);
83	  }
84	  // đã ra ngoài thì lùi lại vào hộp bị chặn
85	  drMove(net, start, 6, 0, boxes, 1, out);
86	  assert.ok(drFits(net, out, boxes, 1, new Uint8Array(1)));
87	  const back = pose(0, 0, 0, 0);
88	  assert.ok(drMove(net, { ...out }, -6, 0, boxes, 1, back) < 1);
89	});
90	
91	test('vật cản thêm lúc chạy vẫn chặn (chỉ mục lưới cập nhật)', () => {
92	  const net = drMakeNet([pad('a', 0, 100, 0, 40, 2.6)], [wall(80, 81, 0, 40, 2.6, 4)]);
93	  const p = pose(50, 2.6, 20, 0);
94	  assert.ok(drFits(net, p, NONE, 0, IGN));                            // dựng lưới
