96	  assert.ok(!drFits(net, p, NONE, 0, IGN));
97	  assert.ok(drFits(net, pose(40, 2.6, 20, 0), NONE, 0, IGN));
98	  assert.ok(!drFits(net, pose(40, 2.6, 38.5, 0), NONE, 0, IGN), 'vật cản lớn (nhiều ô lưới) vẫn chặn');
99	});
100	
101	test('vật cản tầng khác không chặn thân xe', () => {
102	  const net = drMakeNet([pad('a', 0, 100, 0, 40, 2.6)], [wall(40, 60, 0, 40, 8, 9), wall(40, 60, 0, 40, 0, 2.65)]);
