108	  const net = drMakeNet([pad('a', -50, 50, -50, 50, 2.6)], [wall(10, 11, -5, 5, 2.6, 4), { kind: 'circle', cx: 0, cz: 20, r: 1, y0: 2.6, y1: 4 }]);
109	  const t = drSegClear(net, 0, 3.5, 0, 20, 3.5, 0);
