const state = (x: number, z: number, yaw = 0, v = 0, y = 2.6): DrState => ({ x, y, z, yaw, pitch: 0, v, steer: 0, wheel: 0, braking: false, evac: 0 });
const inp = (gas = 0, brake = 0, steer = 0, hand = false): DrInput => ({ gas, brake, steer, hand });
