  for (let i = 0; i < 180; i++) { s.v = 2; drStep(s, g, net, [], 0, DT); }      // 3 s cho góc lái đạt tối đa
  const fx: number[] = [], fz: number[] = [], rx: number[] = [], rz: number[] = [];
